\documentclass{article}

\usepackage{corl_2026} % Submission version: anonymous, line numbers enabled.
% \usepackage[final]{corl_2026} % Uncomment for camera-ready.

\usepackage{amsmath,amssymb}
\usepackage{graphicx}
